import{_ as o,o as a,c as e,a2 as l}from"./chunks/framework.CtrpDQpp.js";const r="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",i="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",d="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",s="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",n="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",c="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",h="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",m="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",p="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",W=JSON.parse('{"title":"第 21 章 功能增强插件推荐","description":"","frontmatter":{},"headers":[],"relativePath":"21-feature-plugins.md","filePath":"21-feature-plugins.md","lastUpdated":1792595797000}'),g={name:"21-feature-plugins.md"};function P(u,t,b,_,q,S){return a(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="第-21-章-功能增强插件推荐" tabindex="-1">第 21 章 功能增强插件推荐 <a class="header-anchor" href="#第-21-章-功能增强插件推荐" aria-label="Permalink to &quot;第 21 章 功能增强插件推荐&quot;">​</a></h1><p>🟡 <strong>进阶难度</strong> ｜ 一句话导览：表单、电商、会员、多语言、SMTP——每个场景都有几十款插件可选。本章不追求「大而全的榜单」，而是按场景给出 1-2 个主流选择、安装后的最小可用配置，以及「什么时候该用、什么时候不该用」的判断标准。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>复用第 16/17 章的选型原则：看更新频率、活跃安装、支持响应、兼容版本</li><li>分场景掌握主流插件的核心配置：表单（Contact Form 7 / WPForms）、电商（WooCommerce）、会员（MemberPress / Paid Member Subscriptions）、多语言（Polylang / WPML）、备份、SMTP（WP Mail SMTP）</li><li>理解每类插件的「最小可用配置」——装好后只做哪些设置就能跑起来</li><li>建立「插件数量迷思」的正确认知：质量 &gt; 数量，但每个插件都是攻击面与维护成本</li><li>遇到表单邮件不进箱、WooCommerce 页面缺失、多语言插件导致固定链接变化时，能快速定位原因</li></ul><h2 id="_21-1-选型原则复用-第-16-17-章的方法论" tabindex="-1">21.1 选型原则复用：第 16/17 章的方法论 <a class="header-anchor" href="#_21-1-选型原则复用-第-16-17-章的方法论" aria-label="Permalink to &quot;21.1 选型原则复用：第 16/17 章的方法论&quot;">​</a></h2><p>在推荐具体插件之前，先复习<a href="./16-plugin-architecture">第 16 章</a>与<a href="./17-plugin-management">第 17 章</a>的核心原则：</p><ul><li><strong>看数字</strong>：活跃安装数、更新频率、兼容版本、支持解决率（第 17.2 节）。</li><li><strong>看架构</strong>：插件是否遵循 WordPress 编码标准、是否有 ABSPATH 守卫、是否用钩子系统而不是直接改核心（第 16 章）。</li><li><strong>看生态</strong>：是否有付费版（说明作者有持续收入，维护意愿强）、是否有丰富的第三方集成（说明社区认可度高）。</li><li><strong>看替代成本</strong>：如果插件停止维护，你的数据能否导出？功能能否被其他插件替代？</li></ul><p>本章推荐的每一款插件都经过上述标准筛选，但<strong>你仍需在测试站验证</strong>——插件与主题的兼容性、与服务器的兼容性，只有实测才知道。</p><h2 id="_21-2-表单插件-contact-form-7-vs-wpforms" tabindex="-1">21.2 表单插件：Contact Form 7 vs WPForms <a class="header-anchor" href="#_21-2-表单插件-contact-form-7-vs-wpforms" aria-label="Permalink to &quot;21.2 表单插件：Contact Form 7 vs WPForms&quot;">​</a></h2><h3 id="_21-2-1-原理说明" tabindex="-1">21.2.1 原理说明 <a class="header-anchor" href="#_21-2-1-原理说明" aria-label="Permalink to &quot;21.2.1 原理说明&quot;">​</a></h3><p>表单是几乎所有网站的刚需：联系我们、报名表、问卷调查。WordPress 核心不提供表单功能，必须用插件。两大主流选择：</p><ul><li><strong>Contact Form 7</strong>：免费、轻量、代码级灵活，适合开发者与极简需求。</li><li><strong>WPForms</strong>：免费版功能完整、拖拽式编辑器、模板丰富，适合非技术用户与复杂表单。</li></ul><h3 id="_21-2-2-contact-form-7-最小可用配置" tabindex="-1">21.2.2 Contact Form 7 最小可用配置 <a class="header-anchor" href="#_21-2-2-contact-form-7-最小可用配置" aria-label="Permalink to &quot;21.2.2 Contact Form 7 最小可用配置&quot;">​</a></h3><ol><li>安装并启用 <code>Contact Form 7</code>。</li><li>进入「联系 → 添加新表单」。</li><li>默认已包含「姓名、邮箱、主题、留言」四个字段，可直接使用，或用标签生成器添加字段（如电话、下拉菜单）。</li><li>「邮件」标签页： <ul><li>「收件人」：默认是站点管理员邮箱（<code>[_site_admin_email]</code>），可改为任意邮箱。</li><li>「发件人」：建议用 <code>wordpress@你的域名</code>（与 SMTP 插件配合，见 21.7 节）。</li><li>「主题」：<code>[your-subject]</code>（用户填写的主题）。</li><li>「消息正文」：默认模板已包含所有字段，可直接用。</li></ul></li><li>复制表单短代码（如 <code>[contact-form-7 id=&quot;123&quot; title=&quot;联系我们&quot;]</code>），粘贴到页面或文章中。</li></ol><p><img src="'+r+'" alt="图 21-1：Contact Form 7 的表单编辑与短代码"></p><p><em>图 21-1：Contact Form 7 用标签语法定义字段，灵活但需一定学习成本。</em></p><p><strong>垃圾防护</strong>：Contact Form 7 本身不带验证码，需配合「Really Simple CAPTCHA」插件或集成 Google reCAPTCHA（「联系 → 集成」）。</p><h3 id="_21-2-3-wpforms-最小可用配置" tabindex="-1">21.2.3 WPForms 最小可用配置 <a class="header-anchor" href="#_21-2-3-wpforms-最小可用配置" aria-label="Permalink to &quot;21.2.3 WPForms 最小可用配置&quot;">​</a></h3><ol><li>安装并启用 <code>WPForms Lite</code>（免费版）。</li><li>进入「WPForms → 添加新表单」。</li><li>选择模板：「简单联系表单」或「空白表单」。</li><li>拖拽编辑器：左侧字段拖到右侧，点击字段可编辑标签、占位符、必填规则。</li><li>「设置 → 通知」： <ul><li>「发送通知到」：默认是管理员邮箱，可改为多个邮箱（用逗号分隔）。</li><li>「邮件主题」：<code>新留言：{field_id=&quot;0&quot;}</code>（<code>{field_id=&quot;0&quot;}</code> 是姓名字段的值）。</li></ul></li><li>「设置 → 确认」：用户提交后显示「谢谢」消息或跳转到感谢页。</li><li>点击「嵌入」按钮，选择页面或复制短代码。</li></ol><p><img src="'+i+'" alt="图 21-2：WPForms 的拖拽式编辑器"></p><p><em>图 21-2：WPForms 的拖拽编辑器零学习成本，适合非技术用户。</em></p><p><strong>垃圾防护</strong>：WPForms 免费版内置蜜罐（Honeypot）反垃圾，付费版支持 reCAPTCHA。</p><h3 id="_21-2-4-表单数据的去向与隐私" tabindex="-1">21.2.4 表单数据的去向与隐私 <a class="header-anchor" href="#_21-2-4-表单数据的去向与隐私" aria-label="Permalink to &quot;21.2.4 表单数据的去向与隐私&quot;">​</a></h3><p>无论 CF7 还是 WPForms，默认行为是「发邮件通知管理员」，但<strong>表单提交内容不一定入库</strong>——CF7 默认不保存提交记录（只发邮件），WPForms 免费版同样只发邮件、付费版才入库。这意味着：</p><ul><li>邮件发送失败 = 留言彻底丢失。所以 SMTP 配置（21.7 节）不是可选项，是表单的命脉。</li><li>需要留存记录的场景（报名表、投诉建议），CF7 配合「Flamingo」插件（同一作者出品）保存提交记录；WPForms 则需付费版。</li><li>涉及个人信息的表单，在隐私政策中说明数据收集用途与保存期限，表单上加一行告知文本。</li></ul><h3 id="_21-2-5-怎么选" tabindex="-1">21.2.5 怎么选 <a class="header-anchor" href="#_21-2-5-怎么选" aria-label="Permalink to &quot;21.2.5 怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Contact Form 7</th><th>WPForms</th></tr></thead><tbody><tr><td>学习成本</td><td>需理解标签语法</td><td>零成本，拖拽即可</td></tr><tr><td>免费版功能</td><td>基础字段 + 邮件通知</td><td>基础字段 + 邮件通知 + 蜜罐反垃圾</td></tr><tr><td>扩展性</td><td>丰富（大量第三方插件）</td><td>付费版解锁高级字段（文件上传、支付、多页表单）</td></tr><tr><td>性能</td><td>轻量，无冗余代码</td><td>稍重，但可接受</td></tr><tr><td>适用人群</td><td>开发者、极简需求</td><td>非技术用户、复杂表单</td></tr></tbody></table><p><strong>建议</strong>：个人博客/小企业官网用 WPForms（免费版够用）；需要高度定制或与其他系统集成的项目用 Contact Form 7。</p><h2 id="_21-3-电商插件-woocommerce" tabindex="-1">21.3 电商插件：WooCommerce <a class="header-anchor" href="#_21-3-电商插件-woocommerce" aria-label="Permalink to &quot;21.3 电商插件：WooCommerce&quot;">​</a></h2><h3 id="_21-3-1-原理说明" tabindex="-1">21.3.1 原理说明 <a class="header-anchor" href="#_21-3-1-原理说明" aria-label="Permalink to &quot;21.3.1 原理说明&quot;">​</a></h3><p>WooCommerce 是 WordPress 官方（Automattic）旗下的电商插件，全球市占率超过 30%。它把 WordPress 变成完整的电商平台：商品管理、购物车、结账、订单管理、支付网关、配送规则、税务计算。</p><p><strong>对数据库与性能的要求</strong>：WooCommerce 会创建 20+ 张自定义表（订单、订单项、优惠券、税率等），并在 <code>wp_posts</code> 与 <code>wp_postmeta</code> 中存储商品数据。一个中型电商站（1000 商品 + 日均 100 订单）的数据库体积会迅速膨胀到 GB 级，查询复杂度也远高于普通博客。<strong>必须配合对象缓存（Redis）与页面缓存（排除购物车/结账页）</strong>，否则后台与前台都会卡。</p><h3 id="_21-3-2-最小可用配置-安装向导" tabindex="-1">21.3.2 最小可用配置：安装向导 <a class="header-anchor" href="#_21-3-2-最小可用配置-安装向导" aria-label="Permalink to &quot;21.3.2 最小可用配置：安装向导&quot;">​</a></h3><ol><li>安装并启用 <code>WooCommerce</code>。</li><li>启用后自动进入安装向导： <ul><li>「店铺基本信息」：填写国家/地区、地址、邮编。</li><li>「行业」：选择最接近的行业（如「电子产品」）。</li><li>「产品类型」：选择「实体产品」「数字产品」或「两者都有」。</li><li>「商业信息」：填写预计年营业额（用于推荐扩展）。</li><li>「主题」：推荐使用官方 Storefront 主题，或保持当前主题（WooCommerce 兼容大多数主题）。</li></ul></li><li>向导完成后，WooCommerce 会自动创建必需页面： <ul><li>「商店」（商品列表页）</li><li>「购物车」</li><li>「结账」</li><li>「我的账户」</li></ul></li></ol><p><img src="'+d+'" alt="图 21-3：WooCommerce 安装向导的产品类型选择"></p><p><em>图 21-3：安装向导会自动创建必需页面，不要手动删除这些页面。</em></p><h3 id="_21-3-3-支付、配送、税的最小闭环" tabindex="-1">21.3.3 支付、配送、税的最小闭环 <a class="header-anchor" href="#_21-3-3-支付、配送、税的最小闭环" aria-label="Permalink to &quot;21.3.3 支付、配送、税的最小闭环&quot;">​</a></h3><p><strong>支付</strong>：</p><ol><li>进入「WooCommerce → 设置 → 支付」。</li><li>启用「直接银行转账」或「支票付款」作为测试支付方式（无需第三方账号）。</li><li>正式运营需配置「支付宝」「微信支付」或「Stripe」——需安装对应网关插件（如「WooCommerce Stripe Gateway」），并填写 API 密钥。</li></ol><p><strong>配送</strong>：</p><ol><li>进入「WooCommerce → 设置 → 配送」。</li><li>添加「配送区域」（如「中国大陆」）。</li><li>在区域内添加「配送方式」（如「全国统一运费 10 元」或「免运费」）。</li></ol><p><strong>税务</strong>：</p><ol><li>进入「WooCommerce → 设置 → 税务」。</li><li>「启用税务」：勾选。</li><li>添加「标准税率」（如中国大陆增值税 13%）。</li><li>「价格输入方式」：选择「含税」或「不含税」（影响商品编辑页的价格输入逻辑）。</li></ol><p><img src="'+s+'" alt="图 21-4：WooCommerce 的支付与配送设置"></p><p><em>图 21-4：支付与配送是电商的最小闭环，必须在上线前跑通一次完整下单流程。</em></p><h3 id="_21-3-4-性能优化要点" tabindex="-1">21.3.4 性能优化要点 <a class="header-anchor" href="#_21-3-4-性能优化要点" aria-label="Permalink to &quot;21.3.4 性能优化要点&quot;">​</a></h3><ul><li><strong>对象缓存</strong>：必须开启 Redis（见<a href="./19-performance-plugins">第 19 章</a>），否则后台订单列表页会随订单量增长而越来越慢。</li><li><strong>页面缓存排除</strong>：购物车、结账、我的账户页面必须加入缓存插件的「不缓存列表」——这些页面是用户私有的，缓存会导致数据错乱。</li><li><strong>数据库清理</strong>：定期清理过期会话（<code>wp_woocommerce_sessions</code> 表）与日志（<code>wp_woocommerce_log</code> 表），可用 WP-CLI 或 WP-Optimize。</li></ul><h3 id="_21-3-5-常见问题" tabindex="-1">21.3.5 常见问题 <a class="header-anchor" href="#_21-3-5-常见问题" aria-label="Permalink to &quot;21.3.5 常见问题&quot;">​</a></h3><p><strong>问：WooCommerce 页面缺失，前台访问 404？</strong> 安装向导会自动创建「商店」「购物车」「结账」「我的账户」四个页面。如果误删或向导中断，可手动重新创建：</p><ol><li>进入「WooCommerce → 状态 → 工具」。</li><li>找到「创建默认 WooCommerce 页面」，点击「创建页面」。</li><li>或手动创建页面，在页面内容中插入对应短代码： <ul><li>商店：无需短代码，在「WooCommerce → 设置 → 产品 → 商店页面」中指定。</li><li>购物车：<code>[woocommerce_cart]</code></li><li>结账：<code>[woocommerce_checkout]</code></li><li>我的账户：<code>[woocommerce_my_account]</code></li></ul></li></ol><p><img src="'+n+'" alt="图 21-5：WooCommerce 状态页的「创建默认页面」工具"></p><p><em>图 21-5：页面缺失时用「创建默认页面」工具一键重建，无需手动建页面。</em></p><h2 id="_21-4-会员-内容限制插件" tabindex="-1">21.4 会员/内容限制插件 <a class="header-anchor" href="#_21-4-会员-内容限制插件" aria-label="Permalink to &quot;21.4 会员/内容限制插件&quot;">​</a></h2><h3 id="_21-4-1-原理说明" tabindex="-1">21.4.1 原理说明 <a class="header-anchor" href="#_21-4-1-原理说明" aria-label="Permalink to &quot;21.4.1 原理说明&quot;">​</a></h3><p>会员插件的核心是「内容限制」——某些页面/文章只对付费会员可见。典型场景：在线课程、付费专栏、会员社区。</p><p>两大主流选择：</p><ul><li><strong>MemberPress</strong>：付费插件（$179/年起），功能最全（会员等级、内容滴灌、优惠券、支付网关集成），适合专业会员站。</li><li><strong>Paid Member Subscriptions</strong>：免费版功能完整（会员等级、内容限制、PayPal 支付），付费版解锁更多支付网关，适合预算有限的起步项目。</li></ul><h3 id="_21-4-2-paid-member-subscriptions-最小可用配置" tabindex="-1">21.4.2 Paid Member Subscriptions 最小可用配置 <a class="header-anchor" href="#_21-4-2-paid-member-subscriptions-最小可用配置" aria-label="Permalink to &quot;21.4.2 Paid Member Subscriptions 最小可用配置&quot;">​</a></h3><ol><li>安装并启用 <code>Paid Member Subscriptions</code>。</li><li>进入「Paid Member Subscriptions → 订阅计划」。</li><li>点击「添加新计划」： <ul><li>「计划名称」：如「月度会员」。</li><li>「价格」：如 <code>30</code>。</li><li>「计费周期」：如「每月」。</li></ul></li><li>「内容限制」： <ul><li>编辑某篇文章，在编辑器下方找到「内容限制」面板。</li><li>勾选「仅限会员」，选择允许访问的订阅计划。</li></ul></li><li>注册/登录表单：插件会自动生成短代码（如 <code>[pms-register]</code>、<code>[pms-login]</code>），插入到页面即可。</li></ol><p><img src="'+c+'" alt="图 21-6：Paid Member Subscriptions 的内容限制面板"></p><p><em>图 21-6：文章编辑页的内容限制面板，勾选后非会员访问会提示「此内容仅限会员」。</em></p><h3 id="_21-4-3-常见问题" tabindex="-1">21.4.3 常见问题 <a class="header-anchor" href="#_21-4-3-常见问题" aria-label="Permalink to &quot;21.4.3 常见问题&quot;">​</a></h3><p><strong>问：会员插件与缓存插件冲突吗？</strong> 会。会员插件依赖「当前用户身份」判断是否显示内容，如果页面缓存把「会员 A 看到的内容」缓存给「非会员 B」，就是严重的数据泄露。<strong>必须</strong>：</p><ul><li>缓存插件的「不缓存已登录用户」必须开启。</li><li>会员专属页面（如「我的课程」）加入缓存排除列表。</li></ul><h2 id="_21-5-多语言插件-polylang-vs-wpml" tabindex="-1">21.5 多语言插件：Polylang vs WPML <a class="header-anchor" href="#_21-5-多语言插件-polylang-vs-wpml" aria-label="Permalink to &quot;21.5 多语言插件：Polylang vs WPML&quot;">​</a></h2><h3 id="_21-5-1-原理说明" tabindex="-1">21.5.1 原理说明 <a class="header-anchor" href="#_21-5-1-原理说明" aria-label="Permalink to &quot;21.5.1 原理说明&quot;">​</a></h3><p>多语言插件分两种架构：</p><ul><li><strong>单站多语言（Polylang / WPML）</strong>：在同一 WordPress 安装中管理多语言内容。每篇文章有多个语言版本，插件负责切换与关联。优点是管理集中、成本低；缺点是数据库复杂度高，所有语言共享同一套主题与插件。</li><li><strong>多站点多语言（WordPress Multisite + 插件）</strong>：每个语言一个子站点（如 <code>cn.example.com</code> 与 <code>en.example.com</code>），内容完全独立。优点是性能与隔离性好；缺点是管理分散、成本高。</li></ul><p><strong>Polylang 与 WPML 的差异</strong>：</p><ul><li><strong>Polylang</strong>：免费版功能完整（文章、页面、分类、菜单的多语言），付费版解锁「同步翻译」（改一篇文章，其他语言自动同步）与「高级 URL 结构」。界面简洁，学习成本低。</li><li><strong>WPML</strong>：付费插件（$39/年起），功能最全（自定义文章类型、自定义字段、WooCommerce 多语言），企业级支持。界面复杂，学习成本高。</li></ul><h3 id="_21-5-2-polylang-最小可用配置" tabindex="-1">21.5.2 Polylang 最小可用配置 <a class="header-anchor" href="#_21-5-2-polylang-最小可用配置" aria-label="Permalink to &quot;21.5.2 Polylang 最小可用配置&quot;">​</a></h3><ol><li>安装并启用 <code>Polylang</code>。</li><li>进入「语言 → 语言」。</li><li>添加语言： <ul><li>添加「中文（简体）」（默认语言）。</li><li>添加「英语」。</li></ul></li><li>「语言 → 设置」： <ul><li>「URL 修改」：选择「语言代码添加到 URL」（如 <code>/cn/about/</code> 与 <code>/en/about/</code>）。</li><li>「检测浏览器语言」：开启。首次访问自动跳转到用户浏览器语言版本。</li></ul></li><li>翻译文章： <ul><li>编辑某篇文章，在「语言」面板选择「中文」。</li><li>点击「+」号创建对应的英文版本，两篇文章自动关联。</li></ul></li></ol><p><img src="'+h+'" alt="图 21-7：Polylang 的文章语言关联面板"></p><p><em>图 21-7：Polylang 在文章编辑页显示语言关联，点击「+」创建对应语言版本。</em></p><h3 id="_21-5-3-多语言的-url-结构选择" tabindex="-1">21.5.3 多语言的 URL 结构选择 <a class="header-anchor" href="#_21-5-3-多语言的-url-结构选择" aria-label="Permalink to &quot;21.5.3 多语言的 URL 结构选择&quot;">​</a></h3><p>Polylang 提供三种 URL 结构，选择前理解各自的 SEO 与维护影响：</p><table tabindex="0"><thead><tr><th>结构</th><th>示例</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>子目录</td><td><code>example.com/cn/about/</code>、<code>example.com/en/about/</code></td><td>集中域名权重；配置最简单</td><td>URL 稍长</td></tr><tr><td>子域名</td><td><code>cn.example.com</code>、<code>en.example.com</code></td><td>各语言可独立部署 CDN</td><td>搜索引擎视为独立站点，权重分散</td></tr><tr><td>独立域名</td><td><code>example.cn</code>、<code>example.com</code></td><td>本地化信号最强</td><td>需购买维护多个域名与证书</td></tr></tbody></table><p><strong>绝大多数站点选子目录</strong>——权重集中、维护简单。子域名与独立域名适合「各语言有独立运营团队」的大型站点。</p><h3 id="_21-5-4-常见问题" tabindex="-1">21.5.4 常见问题 <a class="header-anchor" href="#_21-5-4-常见问题" aria-label="Permalink to &quot;21.5.4 常见问题&quot;">​</a></h3><p><strong>问：多语言插件导致固定链接变化？</strong> 是的。启用 Polylang/WPML 后，URL 会加上语言前缀（如 <code>/about/</code> 变成 <code>/cn/about/</code>）。<strong>必须在启用插件后立即重新保存固定链接</strong>（「设置 → 固定链接 → 保存更改」），否则所有旧链接 404。</p><p><strong>问：已有多语言内容的站点如何迁移？</strong> 如果是从「单语言」迁移到「多语言」，工作量巨大——每篇文章都要手动创建翻译版本并关联。建议在项目初期就决定是否多语言，中途接入成本极高。</p><h2 id="_21-6-备份插件" tabindex="-1">21.6 备份插件 <a class="header-anchor" href="#_21-6-备份插件" aria-label="Permalink to &quot;21.6 备份插件&quot;">​</a></h2><p>备份是网站运维的生命线，但因涉及「备份频率、存储位置、恢复演练」等策略层面内容，本教程将其独立成章。请直接阅读<a href="./34-backup">第 34 章</a>，本章不再重复。</p><p><strong>一句话建议</strong>：如果你现在还没有任何备份机制，立即安装 UpdraftPlus（免费版够用），配置「每周自动备份到云端（如 Google Drive）」，并做一次恢复演练。</p><h2 id="_21-7-smtp-插件-wp-mail-smtp" tabindex="-1">21.7 SMTP 插件：WP Mail SMTP <a class="header-anchor" href="#_21-7-smtp-插件-wp-mail-smtp" aria-label="Permalink to &quot;21.7 SMTP 插件：WP Mail SMTP&quot;">​</a></h2><h3 id="_21-7-1-原理说明" tabindex="-1">21.7.1 原理说明 <a class="header-anchor" href="#_21-7-1-原理说明" aria-label="Permalink to &quot;21.7.1 原理说明&quot;">​</a></h3><p>WordPress 默认用 PHP 的 <code>mail()</code> 函数发邮件，但大多数服务器的 <code>mail()</code> 函数被禁用或邮件进垃圾箱。SMTP 插件把邮件发送交给专业邮件服务商（QQ 邮箱、163 邮箱、Gmail、SendGrid 等），送达率大幅提升。</p><h3 id="_21-7-2-最小可用配置-以-qq-邮箱为例" tabindex="-1">21.7.2 最小可用配置：以 QQ 邮箱为例 <a class="header-anchor" href="#_21-7-2-最小可用配置-以-qq-邮箱为例" aria-label="Permalink to &quot;21.7.2 最小可用配置：以 QQ 邮箱为例&quot;">​</a></h3><ol><li>安装并启用 <code>WP Mail SMTP</code>。</li><li>进入「WP Mail SMTP → 设置」。</li><li>「邮件」标签页： <ul><li>「发件邮箱」：你的 QQ 邮箱（如 <code>yourname@qq.com</code>）。</li><li>「发件人名称」：站点名称。</li><li>「邮件程序」：选择「其他 SMTP」。</li></ul></li><li>「SMTP 主机」：<code>smtp.qq.com</code></li><li>「SMTP 端口」：<code>465</code>（SSL）或 <code>587</code>（TLS）。</li><li>「加密」：选择「SSL」（对应 465 端口）。</li><li>「SMTP 用户名」：你的 QQ 邮箱完整地址。</li><li>「SMTP 密码」：<strong>不是 QQ 密码</strong>，而是 QQ 邮箱的「授权码」： <ul><li>登录 QQ 邮箱网页版 →「设置 → 账户」→「POP3/IMAP/SMTP 服务」→ 开启「IMAP/SMTP 服务」→ 生成授权码。</li><li>把授权码粘贴到「SMTP 密码」。</li></ul></li><li>保存设置，点击「发送测试邮件」验证。</li></ol><p><img src="'+m+'" alt="图 21-8：WP Mail SMTP 的 QQ 邮箱配置"></p><p><em>图 21-8：QQ 邮箱的 SMTP 密码是「授权码」，不是 QQ 登录密码。</em></p><h3 id="_21-7-3-163-邮箱与-gmail-的差异" tabindex="-1">21.7.3 163 邮箱与 Gmail 的差异 <a class="header-anchor" href="#_21-7-3-163-邮箱与-gmail-的差异" aria-label="Permalink to &quot;21.7.3 163 邮箱与 Gmail 的差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>邮箱</th><th>SMTP 主机</th><th>端口</th><th>密码类型</th></tr></thead><tbody><tr><td>QQ 邮箱</td><td><code>smtp.qq.com</code></td><td>465 (SSL)</td><td>授权码（非 QQ 密码）</td></tr><tr><td>163 邮箱</td><td><code>smtp.163.com</code></td><td>465 (SSL)</td><td>授权码（非 163 密码）</td></tr><tr><td>Gmail</td><td><code>smtp.gmail.com</code></td><td>587 (TLS)</td><td>应用专用密码（需开启两步验证）</td></tr></tbody></table><h3 id="_21-7-4-常见问题" tabindex="-1">21.7.4 常见问题 <a class="header-anchor" href="#_21-7-4-常见问题" aria-label="Permalink to &quot;21.7.4 常见问题&quot;">​</a></h3><p><strong>问：表单邮件不进箱，都进垃圾箱？</strong></p><ul><li>确认已配置 SMTP 插件，且测试邮件能收到。</li><li>检查发件域名是否有 SPF/DKIM 记录（在 DNS 管理中添加，具体记录值问你的邮件服务商）。</li><li>避免在邮件主题与正文中使用「免费」「促销」「点击领取」等垃圾邮件关键词。</li><li>如果仍进垃圾箱，换用专业邮件服务（SendGrid、Amazon SES、阿里云邮件推送），送达率更高。</li></ul><h2 id="_21-8-安全与性能插件的交叉引用" tabindex="-1">21.8 安全与性能插件的交叉引用 <a class="header-anchor" href="#_21-8-安全与性能插件的交叉引用" aria-label="Permalink to &quot;21.8 安全与性能插件的交叉引用&quot;">​</a></h2><p>安全类插件（Wordfence、Sucuri）与性能类插件（WP Super Cache、Redis Object Cache）已在<a href="./18-security-plugins">第 18 章</a>与<a href="./19-performance-plugins">第 19 章</a>详细讲解，本章不再重复。</p><p><strong>交叉注意事项</strong>：</p><ul><li>安全插件的「登录保护」与会员插件的「会员登录」可能冲突——测试会员注册/登录流程时，先用白名单 IP 或临时停用安全插件。</li><li>缓存插件的「页面缓存」与安全插件的「实时流量监控」不冲突，但「对象缓存」可能缓存安全插件的规则，导致规则更新延迟——配置安全插件后，手动清一次对象缓存。</li></ul><h3 id="_21-8-1-推荐基线组合" tabindex="-1">21.8.1 推荐基线组合 <a class="header-anchor" href="#_21-8-1-推荐基线组合" aria-label="Permalink to &quot;21.8.1 推荐基线组合&quot;">​</a></h3><p>把前面章节与本章的内容汇总，一个普通企业官网的「插件基线」可以这样组合：</p><table tabindex="0"><thead><tr><th>层</th><th>插件</th><th>来源章节</th></tr></thead><tbody><tr><td>安全</td><td>Wordfence（免费版）</td><td>第 18 章</td></tr><tr><td>页面缓存</td><td>WP Super Cache</td><td>第 19 章</td></tr><tr><td>对象缓存</td><td>Redis Object Cache</td><td>第 19 章</td></tr><tr><td>SEO</td><td>Yoast SEO</td><td>第 20 章</td></tr><tr><td>表单</td><td>WPForms Lite</td><td>本章 21.2</td></tr><tr><td>SMTP</td><td>WP Mail SMTP</td><td>本章 21.7</td></tr><tr><td>图片优化</td><td>ShortPixel</td><td>本章 21.9</td></tr><tr><td>备份</td><td>UpdraftPlus</td><td>第 34 章</td></tr></tbody></table><p>八个插件覆盖安全、性能、SEO、转化四大需求，且全部是「免费版即可用、付费版有明确升级理由」的成熟产品。在这个基线之上，按业务需要再加电商/会员/多语言插件。</p><h2 id="_21-9-图片优化插件" tabindex="-1">21.9 图片优化插件 <a class="header-anchor" href="#_21-9-图片优化插件" aria-label="Permalink to &quot;21.9 图片优化插件&quot;">​</a></h2><h3 id="_21-9-1-原理说明" tabindex="-1">21.9.1 原理说明 <a class="header-anchor" href="#_21-9-1-原理说明" aria-label="Permalink to &quot;21.9.1 原理说明&quot;">​</a></h3><p>图片通常占网页体积的 50% 以上，是性能优化的最大单一杠杆。图片优化插件做三件事：上传时自动压缩（有损/无损）、转换为现代格式（WebP/AVIF，体积比 JPEG 小 30-50%）、按需生成多尺寸缩略图。</p><p>主流选择：</p><ul><li><strong>Smush</strong>：免费版支持无损压缩与延迟加载，批量处理历史图片（免费版每次限 50 张）；付费版解锁 WebP 转换与 CDN。</li><li><strong>ShortPixel</strong>：压缩率更高，免费额度每月 100 张，支持 WebP/AVIF；超出后按量付费，适合图片量大的站。</li></ul><h3 id="_21-9-2-shortpixel-最小可用配置" tabindex="-1">21.9.2 ShortPixel 最小可用配置 <a class="header-anchor" href="#_21-9-2-shortpixel-最小可用配置" aria-label="Permalink to &quot;21.9.2 ShortPixel 最小可用配置&quot;">​</a></h3><ol><li>安装并启用 <code>ShortPixel Image Optimizer</code>。</li><li>到 shortpixel.com 用邮箱注册，获得 API Key（免费额度即够用）。</li><li>进入「设置 → ShortPixel」，粘贴 API Key。</li><li>「常规」标签页： <ul><li>「压缩类型」：选「有损（Lossy）」——视觉差异肉眼几乎不可见，体积收益最大；摄影类站点选「光泽（Glossy）」。</li><li>「生成 WebP 版本」：勾选。</li><li>「调整大图尺寸」：勾选，最大边长设为 2048px（手机拍摄的原图通常 4000px+，网页完全用不到）。</li></ul></li><li>「批量处理」：进入「媒体 → 批量 ShortPixel」，一键处理历史图片。</li></ol><p><img src="'+A+'" alt="图 21-9：ShortPixel 的压缩类型与 WebP 设置"></p><p><em>图 21-9：有损压缩 + WebP + 限制大图尺寸，是图片优化的三个最高收益开关。</em></p><h3 id="_21-9-3-常见问题" tabindex="-1">21.9.3 常见问题 <a class="header-anchor" href="#_21-9-3-常见问题" aria-label="Permalink to &quot;21.9.3 常见问题&quot;">​</a></h3><p><strong>问：图片压缩会影响画质吗？</strong> 无损压缩完全不影响；有损压缩（质量 80-90%）在网页展示场景下肉眼几乎无法分辨。如果你对某张图的画质极其敏感（如作品集），可在媒体库中对该图单独选择「不压缩」。</p><p><strong>问：WebP 图片老浏览器不支持怎么办？</strong> 插件会用 <code>&lt;picture&gt;</code> 标签输出——现代浏览器加载 WebP，老浏览器自动回退到原格式 JPEG/PNG，无需手动处理。</p><h2 id="_21-10-插件数量迷思" tabindex="-1">21.10 插件数量迷思 <a class="header-anchor" href="#_21-10-插件数量迷思" aria-label="Permalink to &quot;21.10 插件数量迷思&quot;">​</a></h2><h3 id="_21-10-1-原理说明" tabindex="-1">21.10.1 原理说明 <a class="header-anchor" href="#_21-10-1-原理说明" aria-label="Permalink to &quot;21.10.1 原理说明&quot;">​</a></h3><p>「插件数量多 = 网站慢」是流传最广的误解之一。真相是：</p><ul><li><strong>质量 &gt; 数量</strong>：10 个编码规范、按需加载的插件，比 1 个全站加载冗余代码的插件更快。</li><li><strong>每个插件都是攻击面</strong>：插件越多，潜在漏洞越多，需要更新的频率越高。</li><li><strong>每个插件都是维护成本</strong>：插件更新可能引入兼容性问题，插件停止维护可能导致功能失效。</li></ul><p><strong>关键指标</strong>：不是「装了多少个」，而是「每个插件是否真的必要」「是否有更轻量的替代方案」「是否长期不更新」。</p><h3 id="_21-10-2-操作方法-插件审计" tabindex="-1">21.10.2 操作方法：插件审计 <a class="header-anchor" href="#_21-10-2-操作方法-插件审计" aria-label="Permalink to &quot;21.10.2 操作方法：插件审计&quot;">​</a></h3><p>每季度做一次插件审计：</p><ol><li>进入「插件 → 已安装的插件」。</li><li>逐个插件问自己： <ul><li>这个插件的功能还在用吗？（很多站点装了「即将上线」插件，上线后忘了删）</li><li>这个插件上次更新是什么时候？（超过 1 年未更新，考虑替代方案）</li><li>这个插件的功能能否用更轻量的方式实现？（如「Google Analytics」插件可用「在主题 header.php 插入代码」替代）</li></ul></li><li>停用并删除「不再使用」的插件。</li><li>对「长期不更新但功能必需」的插件，在测试站验证其与当前 WordPress 版本的兼容性，并关注官方库的安全公告。</li></ol><p><img src="'+p+'" alt="图 21-10：插件审计清单"></p><p><em>图 21-10：每季度做一次插件审计，删除不再使用的插件，减少攻击面与维护成本。</em></p><h2 id="_21-11-常见问题速查" tabindex="-1">21.11 常见问题速查 <a class="header-anchor" href="#_21-11-常见问题速查" aria-label="Permalink to &quot;21.11 常见问题速查&quot;">​</a></h2><h3 id="_21-11-1-表单邮件不进箱" tabindex="-1">21.11.1 表单邮件不进箱 <a class="header-anchor" href="#_21-11-1-表单邮件不进箱" aria-label="Permalink to &quot;21.11.1 表单邮件不进箱&quot;">​</a></h3><p>见 21.7.4 节。</p><h3 id="_21-11-2-woocommerce-页面缺失" tabindex="-1">21.11.2 WooCommerce 页面缺失 <a class="header-anchor" href="#_21-11-2-woocommerce-页面缺失" aria-label="Permalink to &quot;21.11.2 WooCommerce 页面缺失&quot;">​</a></h3><p>见 21.3.5 节。</p><h3 id="_21-11-3-多语言插件导致固定链接变化" tabindex="-1">21.11.3 多语言插件导致固定链接变化 <a class="header-anchor" href="#_21-11-3-多语言插件导致固定链接变化" aria-label="Permalink to &quot;21.11.3 多语言插件导致固定链接变化&quot;">​</a></h3><p>见 21.5.3 节。</p><h3 id="_21-11-4-插件冲突导致功能异常" tabindex="-1">21.11.4 插件冲突导致功能异常 <a class="header-anchor" href="#_21-11-4-插件冲突导致功能异常" aria-label="Permalink to &quot;21.11.4 插件冲突导致功能异常&quot;">​</a></h3><p>回到<a href="./17-plugin-management#_17-6-插件冲突排查法">第 17 章 17.6 节</a>的二分停用法与健康检查故障排除模式。</p><h3 id="_21-11-5-商业插件到期后不续费会怎样" tabindex="-1">21.11.5 商业插件到期后不续费会怎样 <a class="header-anchor" href="#_21-11-5-商业插件到期后不续费会怎样" aria-label="Permalink to &quot;21.11.5 商业插件到期后不续费会怎样&quot;">​</a></h3><p><strong>现象</strong>：MemberPress、WP Rocket 等商业插件的授权到期，犹豫要不要续费。</p><p><strong>事实</strong>：绝大多数商业插件到期后<strong>功能继续可用</strong>，失去的只是：① 后续版本更新（包括安全修复）；② 官方技术支持；③ 部分云端服务（如 ShortPixel 的 API 额度、某些插件的模板库）。</p><p><strong>风险评估</strong>：功能继续用不是问题，问题在「停止更新」——安全漏洞修复也随之中断。如果你的站点仍在运营，续费本质上是「为安全更新付费」；如果决定不续，把该插件列入 21.10 插件审计的重点观察名单，一旦爆出漏洞立即更换方案。</p><h3 id="_21-11-6-付费插件的「续费提醒」轰炸" tabindex="-1">21.11.6 付费插件的「续费提醒」轰炸 <a class="header-anchor" href="#_21-11-6-付费插件的「续费提醒」轰炸" aria-label="Permalink to &quot;21.11.6 付费插件的「续费提醒」轰炸&quot;">​</a></h3><p><strong>现象</strong>：WP Rocket、MemberPress 等付费插件在后台频繁弹出续费提醒，关闭后下次登录又出现。</p><p><strong>处理</strong>：正规商业插件的提醒可以永久关闭（点击「Dismiss」或「不再显示」）。如果无法关闭，在「WP Mail SMTP → 邮件控制」或「Yoast SEO → 常规」中找到「后台通知」开关。对持续骚扰的插件，可在主题的 <code>functions.php</code> 中用 CSS 隐藏（见<a href="./16-plugin-architecture">第 22 章</a>的钩子示例）。</p><p><strong>预防</strong>：购买付费插件前，先读官方文档的「支持与更新」政策，确认「买断制」（一次付费终身使用）还是「订阅制」（每年续费）。买断制更适合个人站，订阅制更适合持续运营的商业站。</p><h3 id="_21-11-7-免费版-vs-付费版怎么决策" tabindex="-1">21.11.7 免费版 vs 付费版怎么决策 <a class="header-anchor" href="#_21-11-7-免费版-vs-付费版怎么决策" aria-label="Permalink to &quot;21.11.7 免费版 vs 付费版怎么决策&quot;">​</a></h3><p>一个简单的决策框架，按顺序回答：</p><ol><li><strong>免费版功能是否覆盖当前需求？</strong> 覆盖 → 用免费版，不纠结。</li><li><strong>缺失的功能是「现在就要」还是「以后可能要」？</strong> 以后可能要 → 先用免费版，需要时再升级。</li><li><strong>付费版的价格 vs 自建成本？</strong> 插件 $59/年，自建同等功能需要 20 小时开发 → 付费几乎总是划算的。</li><li><strong>该插件是不是核心业务的单点依赖？</strong> 是（如电商的支付网关）→ 优先付费，购买的是「持续维护」的确定性。</li></ol><h2 id="本章总结" tabindex="-1">本章总结 <a class="header-anchor" href="#本章总结" aria-label="Permalink to &quot;本章总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐插件</th><th>最小可用配置</th><th>易错点</th></tr></thead><tbody><tr><td>表单</td><td>Contact Form 7（开发者）/ WPForms（非技术用户）</td><td>CF7：邮件标签页配置收件人；WPForms：拖拽编辑器 + 通知设置</td><td>垃圾防护需配合 reCAPTCHA 或蜜罐</td></tr><tr><td>电商</td><td>WooCommerce</td><td>安装向导 → 支付/配送/税最小闭环</td><td>必须配合对象缓存与页面缓存排除</td></tr><tr><td>会员</td><td>MemberPress（专业）/ Paid Member Subscriptions（起步）</td><td>订阅计划 + 内容限制面板</td><td>与缓存插件冲突，需排除会员页面</td></tr><tr><td>多语言</td><td>Polylang（简洁）/ WPML（企业级）</td><td>添加语言 → URL 加语言前缀 → 文章关联翻译</td><td>启用后立即重新保存固定链接</td></tr><tr><td>备份</td><td>UpdraftPlus</td><td>每周自动备份到云端</td><td>见第 34 章</td></tr><tr><td>SMTP</td><td>WP Mail SMTP</td><td>QQ/163 邮箱授权码配置</td><td>授权码不是登录密码</td></tr><tr><td>图片优化</td><td>Smush / ShortPixel</td><td>有损压缩 + WebP + 限制大图 2048px</td><td>压缩 API 有免费额度，超量需付费</td></tr><tr><td>安全/性能</td><td>见第 18/19 章</td><td>—</td><td>安全插件与会员插件可能冲突</td></tr><tr><td>插件数量</td><td>质量 &gt; 数量</td><td>每季度插件审计</td><td>每个插件都是攻击面与维护成本</td></tr></tbody></table><h2 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h2><p><strong>练-21-01（操作题）｜用 WPForms 建一个联系表单</strong></p><p>在练习站安装 WPForms Lite，用「简单联系表单」模板创建一个表单，添加「电话」字段（必填），配置通知邮件发送到你的邮箱，把表单嵌入到「联系我们」页面。提交一次测试留言，确认能收到邮件（需先配置 SMTP，见练-21-04）。</p><p><strong>练-21-02（操作题）｜WooCommerce 最小闭环</strong></p><p>在练习站安装 WooCommerce，走完安装向导，创建一个测试商品（价格 99 元），配置「直接银行转账」支付与「全国统一运费 10 元」，用游客身份走一遍完整下单流程（加购物车 → 结账 → 下单成功）。截图订单详情页。</p><p><strong>练-21-03（分析题）｜Polylang 与 WPML 的架构差异</strong></p><p>阅读 Polylang 与 WPML 的官方文档，用 21.5.1 的两个维度（单站多语言 vs 多站点多语言、Polylang vs WPML 的功能差异）各写一段 200 字总结。如果是一个 5 语言的企业官网（中/英/日/韩/德），你会选哪个插件？为什么？</p><p><strong>练-21-04（操作题）｜配置 QQ 邮箱 SMTP</strong></p><p>在练习站安装 WP Mail SMTP，按 21.7.2 配置 QQ 邮箱 SMTP（需先在 QQ 邮箱网页版生成授权码），发送测试邮件验证。然后用 Contact Form 7 或 WPForms 提交一次表单，确认邮件进收件箱而非垃圾箱。如果进垃圾箱，按 21.7.4 排查 SPF/DKIM 记录。</p><p><strong>练-21-05（综合题）｜为一个在线课程站选型</strong></p><p>假设你要搭建一个在线课程站：付费视频课程（会员制）、课程讨论区、讲师与学员的私信、每周邮件通知新课程。请写出完整的插件选型清单：会员插件选哪个、讨论区用什么（插件或外链论坛）、私信用什么、邮件通知用什么（SMTP + 邮件模板插件）、缓存与安全插件怎么配合。每一项说明「选它的理由」与「不选替代方案的理由」。</p>',159)])])}const x=o(g,[["render",P]]);export{W as __pageData,x as default};
